TYPE DriveSettings :
STRUCT
 Enabled : BOOL;
 Speed : INT;
END_STRUCT
END_TYPE

TYPE MachineSettings :
STRUCT
 Label : STRING(80);
 Limits : ARRAY[0..2] OF INT;
 Drive : DriveSettings;
END_STRUCT
END_TYPE

change.implementation:
MotorLD();
InitFBD();
Sequence(Start := MotorLD.Running, Stop := NOT MotorLD.Running);
IF Sequence.CycleActive AND NOT PreviousActive THEN
 InitFBD.TotalCycles := InitFBD.TotalCycles + 1;
END_IF;
PreviousActive := Sequence.CycleActive;

